def cd(folder):
    import json, os, math, random
    _S = json.load(open(os.path.join(_DB, 'state.json'), encoding='utf-8'))
    nodes = _S.get("nodes", {})
    cwd = _S.get("cwd", "/")
    def _join(base, name):
        if base == "/":
            return "/" + name
        return base + "/" + name
    def _children(dirpath):
        node = nodes.get(dirpath)
        if not node or node.get("type") != "directory":
            return []
        return node.get("children", [])

    folder = folder.rstrip("/")
    if folder == "":
        folder = "/"
    if folder not in {".", "..", "/"} and "/" in folder:
        return {"error": f"cd: {folder}: Unsupported path. Only one folder level at a time is supported."}
    if folder == "..":
        if cwd == _S.get("cwd_root", "/" + _S.get("root_name", "")) or cwd.count("/") <= 1:
            parent = "/".join(cwd.split("/")[:-1]) or "/"
            if parent == "":
                parent = "/"
            return {"current_working_directory": parent} if parent != cwd else {"error": "Current directory is already the root. Cannot go back."}
        parent = "/".join(cwd.split("/")[:-1]) or "/"
        return {"current_working_directory": parent}
    target = _join(cwd, folder)
    node = nodes.get(target)
    if not node or node.get("type") != "directory":
        return {"error": f"cd: {folder}: No such file or directory"}
    return {"current_working_directory": target}

