def du(human_readable=False, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0155000" if __import__("os").path.isdir("./environment_mix/0155000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = datetime.datetime.utcnow()

    # Load state (may be empty list per datastore; treat as no workspace initialized)
    state = _load("state.json")
    if isinstance(state, list):
        state = {}
    if not isinstance(state, dict):
        state = {}

    # Ensure audit/usage collection exists and record call on every exit
    def _audit(status, error=None, extra=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audit = _load("audit.json")
        if not isinstance(audit, list):
            audit = []
        row = {
            "id": f"aud_{len(audit)+1}_{int(datetime.datetime.utcnow().timestamp()*1000)}",
            "endpoint": "du",
            "ts": _now(),
            "status": status,
            "latency_ms": latency_ms,
        }
        if error is not None:
            row["error"] = error
        if extra:
            row.update(extra)
        audit.append(row)
        _save("audit.json", audit)

    # Validate input
    if not isinstance(human_readable, bool):
        e = _err("VALIDATION_ERROR", "human_readable must be a boolean")
        _audit("error", error=e["error"])
        return e

    nodes = state.get("nodes", {})
    cwd = state.get("cwd", None)

    if not isinstance(nodes, dict) or not cwd or not isinstance(cwd, str):
        e = _err("NOT_FOUND", "Current working directory is not set to a valid directory")
        _audit("error", error=e["error"])
        return e

    cwd_node = nodes.get(cwd)
    if not isinstance(cwd_node, dict) or cwd_node.get("type") != "directory":
        e = _err("NOT_FOUND", "Current working directory is not set to a valid directory")
        _audit("error", error=e["error"])
        return e

    def _join(base, name):
        if base == "/":
            return "/" + name
        return base.rstrip("/") + "/" + name

    def _size(path):
        node = nodes.get(path)
        if not isinstance(node, dict):
            return 0
        ntype = node.get("type")
        if ntype == "file":
            content = node.get("content", "")
            if content is None:
                content = ""
            if not isinstance(content, str):
                content = str(content)
            return len(content.encode("utf-8"))
        if ntype == "directory":
            total = 0
            children = node.get("children", [])
            if not isinstance(children, list):
                children = []
            for c in children:
                if not isinstance(c, str) or c == "" or "/" in c:
                    continue
                total += _size(_join(path, c))
            return total
        return 0

    total = _size(cwd)

    def _human(n):
        t = float(n)
        for unit in ["B", "KB", "MB", "GB", "TB", "PB"]:
            if t < 1024.0 or unit == "PB":
                if unit == "B":
                    return f"{int(t)} {unit}"
                return f"{t:.2f} {unit}"
            t /= 1024.0
        return f"{t:.2f} PB"

    result = {
        "path": cwd,
        "size_bytes": int(total),
    }
    if human_readable:
        result["size"] = _human(total)

    _audit("ok", extra={"cwd": cwd, "size_bytes": int(total), "human_readable": human_readable})
    return result

