def find(path='.', name=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0155000" if __import__("os").path.isdir("./environment_mix/0155000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = datetime.datetime.utcnow()

    # Load state
    state = _load("state.json")
    if isinstance(state, list):
        state = {}
    if not isinstance(state, dict):
        state = {}

    def _audit(status, error=None, extra=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audit = _load("audit.json")
        if not isinstance(audit, list):
            audit = []
        row = {
            "id": f"aud_{len(audit)+1}_{int(datetime.datetime.utcnow().timestamp()*1000)}",
            "endpoint": "find",
            "ts": _now(),
            "status": status,
            "latency_ms": latency_ms,
        }
        if error is not None:
            row["error"] = error
        if extra:
            row.update(extra)
        audit.append(row)
        _save("audit.json", audit)

    # Validate inputs
    if path is None:
        path = "."
    if not isinstance(path, str):
        e = _err("VALIDATION_ERROR", "path must be a string")
        _audit("error", error=e["error"])
        return e

    if name is not None:
        if not isinstance(name, str):
            e = _err("VALIDATION_ERROR", "name must be a string or None")
            _audit("error", error=e["error"])
            return e
        # must be a single entry name, not path-like
        if name == "" or "/" in name or name in (".", ".."):
            e = _err("VALIDATION_ERROR", "name must be a single entry name (not path-like)")
            _audit("error", error=e["error"])
            return e

    # Path must be valid within workspace; refuse obvious invalidities
    # Allow: ".", "", "/", absolute like "/a/b", or relative like "a/b"
    if "\x00" in path:
        e = _err("VALIDATION_ERROR", "path contains invalid characters")
        _audit("error", error=e["error"])
        return e
    if ".." in [p for p in path.split("/") if p != ""]:
        e = _err("VALIDATION_ERROR", "path must be valid within the workspace (no '..' segments)")
        _audit("error", error=e["error"])
        return e

    nodes = state.get("nodes", {})
    cwd = state.get("cwd", None)

    if not isinstance(nodes, dict) or not isinstance(cwd, str) or not cwd:
        e = _err("NOT_FOUND", "Start path does not exist or is not a directory")
        _audit("error", error=e["error"])
        return e

    def _join(base, part):
        if base == "/":
            return "/" + part
        return base.rstrip("/") + "/" + part

    def _norm_abs(p):
        if p in ("", "."):
            return cwd
        if p == "/":
            return "/"
        if p.startswith("/"):
            return "/" + "/".join([seg for seg in p.split("/") if seg != ""])
        # relative
        rel = "/".join([seg for seg in p.split("/") if seg != ""])
        return _join(cwd, rel) if rel else cwd

    start_abs = _norm_abs(path)

    start_node = nodes.get(start_abs)
    if not isinstance(start_node, dict) or start_node.get("type") != "directory":
        e = _err("NOT_FOUND", "Start path does not exist or is not a directory", path=path)
        _audit("error", error=e["error"])
        return e

    def _children(dir_abs):
        node = nodes.get(dir_abs)
        if not isinstance(node, dict) or node.get("type") != "directory":
            return []
        ch = node.get("children", [])
        if not isinstance(ch, list):
            return []
        # only valid entry names
        out = []
        for c in ch:
            if isinstance(c, str) and c != "" and "/" not in c and c not in (".", ".."):
                out.append(c)
        return out

    # Return paths relative to the requested start directory, like typical find output.
    matches = []

    def _walk(dir_abs, rel_prefix):
        for entry in _children(dir_abs):
            child_abs = _join(dir_abs, entry)
            child_rel = entry if rel_prefix == "" else rel_prefix + "/" + entry
            if name is None or entry == name:
                matches.append(child_rel)
            child_node = nodes.get(child_abs)
            if isinstance(child_node, dict) and child_node.get("type") == "directory":
                _walk(child_abs, child_rel)

    _walk(start_abs, "")

    result = {
        "start": path,
        "start_resolved": start_abs,
        "name": name,
        "matches": matches,
        "count": len(matches),
    }
    _audit("ok", extra={"start_resolved": start_abs, "count": len(matches), "filtered": name is not None})
    return result

